-- Schema-only test fixture. No account or channel data.
CREATE TABLE `playlists` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `url` TEXT NOT NULL, `is_vod` INTEGER NOT NULL, `is_enabled` INTEGER NOT NULL, `auto_update` INTEGER NOT NULL, `update_interval_hours` INTEGER NOT NULL, `last_update_time` INTEGER NOT NULL, `include_tv_channels` INTEGER NOT NULL, `include_vod` INTEGER NOT NULL, `is_expanded` INTEGER NOT NULL, `is_expanded_in_movies` INTEGER NOT NULL, `is_expanded_in_series` INTEGER NOT NULL, `tvg_urls` TEXT NOT NULL, `tvg_shift` INTEGER NOT NULL, `server_timezone` TEXT, `expiration_date` INTEGER, `max_connections` INTEGER, `channel_count` INTEGER NOT NULL, `movie_count` INTEGER NOT NULL, `series_count` INTEGER NOT NULL, `catchup_type` INTEGER, `catchup_hours` INTEGER, `catchup_source` TEXT, `user_catchup_type` INTEGER, `user_catchup_hours` INTEGER, `user_catchup_time_offset` INTEGER, `is_visible_in_all_channels` INTEGER NOT NULL, `is_visible_in_all_favorites` INTEGER NOT NULL, `logos_priority` INTEGER NOT NULL, `groups_sorting` INTEGER NOT NULL, `prev_groups_sorting` INTEGER NOT NULL, `movie_groups_sorting` INTEGER NOT NULL, `prev_movie_groups_sorting` INTEGER NOT NULL, `series_groups_sorting` INTEGER NOT NULL, `prev_series_groups_sorting` INTEGER NOT NULL, `position` INTEGER, `stalker_token` TEXT, `user_agent` TEXT, `are_new_groups_visible` INTEGER NOT NULL, `are_new_movie_groups_visible` INTEGER NOT NULL, `are_new_series_groups_visible` INTEGER NOT NULL);
CREATE TABLE `channels` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playlist_id` INTEGER NOT NULL, `xc_id` INTEGER, `stalker_id` INTEGER, `name` TEXT NOT NULL, `custom_name` TEXT, `url` TEXT NOT NULL, `logo` TEXT NOT NULL, `original_group_id` INTEGER, `tvg_id` TEXT NOT NULL, `tvg_name` TEXT NOT NULL, `tvg_shift` INTEGER NOT NULL, `tvg_ch_no` INTEGER NOT NULL, `drm_scheme` TEXT NOT NULL, `drm_license_url` TEXT NOT NULL, `server_timezone` TEXT, `catchup_type` INTEGER, `catchup_hours` INTEGER, `catchup_source` TEXT, `position_in_playlist` INTEGER, `position_in_group` INTEGER NOT NULL, `is_visible` INTEGER NOT NULL, `is_blocked` INTEGER NOT NULL, `is_favorite` INTEGER NOT NULL, `last_turn_on_time` INTEGER NOT NULL, `last_group_id` INTEGER, `last_group_type_id` INTEGER NOT NULL, `last_group_playlist_id` INTEGER NOT NULL, `watch_time` INTEGER NOT NULL, `audio_track_selection` TEXT, `video_track_selection` TEXT, `closed_captions_selection` TEXT, `display_mode` INTEGER NOT NULL, `audio_offset` INTEGER, `user_tvg_id` TEXT NOT NULL, `user_tvg_source_id` INTEGER, `user_tvg_time_offset` INTEGER, `blocked_tvg_ids` TEXT NOT NULL, `audio_decoder_priority` INTEGER, `video_decoder_priority` INTEGER, `use_external_player` INTEGER, `deleted_time` INTEGER, FOREIGN KEY(`playlist_id`) REFERENCES `playlists`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`original_group_id`) REFERENCES `channel_groups`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL , FOREIGN KEY(`last_group_id`) REFERENCES `channel_groups`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL , FOREIGN KEY(`user_tvg_source_id`) REFERENCES `tvg_sources`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE TABLE `channel_groups` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playlist_id` INTEGER, `xc_id` INTEGER, `stalker_id` INTEGER, `name` TEXT NOT NULL, `is_custom` INTEGER NOT NULL, `position_in_playlist` INTEGER, `deleted_time` INTEGER, FOREIGN KEY(`playlist_id`) REFERENCES `playlists`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `channel_group_links` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `channel_id` INTEGER NOT NULL, `group_id` INTEGER NOT NULL, FOREIGN KEY(`channel_id`) REFERENCES `channels`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`group_id`) REFERENCES `channel_groups`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `tvg_sources` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playlist_id` INTEGER, `type` INTEGER NOT NULL, `name` TEXT NOT NULL, `url` TEXT NOT NULL, `time_offset` INTEGER NOT NULL, `etag` TEXT, `last_modified` TEXT, `last_file_size` INTEGER, `last_update_time` INTEGER NOT NULL, FOREIGN KEY(`playlist_id`) REFERENCES `playlists`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `playlist_tvg_source_assignments` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playlist_id` INTEGER NOT NULL, `tvg_source_id` INTEGER, `priority` INTEGER NOT NULL, FOREIGN KEY(`playlist_id`) REFERENCES `playlists`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`tvg_source_id`) REFERENCES `tvg_sources`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `channel_group_options` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `type` INTEGER NOT NULL, `playlist_id` INTEGER NOT NULL, `group_id` INTEGER, `custom_group_name` TEXT, `sorting` INTEGER NOT NULL, `prev_sorting` INTEGER NOT NULL, `is_visible` INTEGER NOT NULL, `is_blocked` INTEGER, `are_favorites_only` INTEGER NOT NULL, `use_external_player` INTEGER, `manual_position` INTEGER, `tvg_time_offset` INTEGER, FOREIGN KEY(`group_id`) REFERENCES `channel_groups`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `channel_manual_positions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `channel_id` INTEGER NOT NULL, `type` INTEGER NOT NULL, `playlist_id` INTEGER NOT NULL, `group_id` INTEGER, `position` INTEGER NOT NULL, FOREIGN KEY(`channel_id`) REFERENCES `channels`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`group_id`) REFERENCES `channel_groups`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `movies` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playlist_id` INTEGER NOT NULL, `category_id` INTEGER, `xc_id` INTEGER, `stalker_id` INTEGER, `stalker_json` TEXT, `name` TEXT NOT NULL, `url` TEXT, `image` TEXT, `rating` REAL, `added_time` INTEGER, `drm_scheme` TEXT, `drm_license_url` TEXT, `position_in_category` INTEGER, `audio_track_selection` TEXT, `video_track_selection` TEXT, `closed_captions_selection` TEXT, `display_mode` INTEGER NOT NULL, `audio_offset` INTEGER, `is_favorite` INTEGER, `last_turn_on_time` INTEGER, `last_played_position_ms` INTEGER, `duration_ms` INTEGER, `deleted_time` INTEGER, FOREIGN KEY(`playlist_id`) REFERENCES `playlists`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`category_id`) REFERENCES `movie_categories`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE TABLE `series` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playlist_id` INTEGER NOT NULL, `category_id` INTEGER, `xc_id` INTEGER, `stalker_id` INTEGER, `stalker_json` TEXT, `name` TEXT NOT NULL, `image` TEXT, `rating` REAL, `last_modified_time` INTEGER, `position_in_category` INTEGER, `audio_track_selection` TEXT, `video_track_selection` TEXT, `closed_captions_selection` TEXT, `display_mode` INTEGER NOT NULL, `audio_offset` INTEGER, `is_favorite` INTEGER, `last_turn_on_time` INTEGER, `last_episode_xc_id` INTEGER, `deleted_time` INTEGER, FOREIGN KEY(`playlist_id`) REFERENCES `playlists`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`category_id`) REFERENCES `series_categories`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE TABLE `movie_categories` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playlist_id` INTEGER NOT NULL, `xc_id` INTEGER, `stalker_id` INTEGER, `stalker_genre_id` INTEGER, `stalker_type` TEXT, `item_count` INTEGER, `name` TEXT NOT NULL, `is_visible` INTEGER NOT NULL, `manual_position` INTEGER, `position_in_playlist` INTEGER, `max_movie_added_time` INTEGER, `deleted_time` INTEGER, FOREIGN KEY(`playlist_id`) REFERENCES `playlists`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `series_categories` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playlist_id` INTEGER NOT NULL, `xc_id` INTEGER, `stalker_id` INTEGER, `stalker_genre_id` INTEGER, `stalker_type` TEXT, `item_count` INTEGER, `name` TEXT NOT NULL, `is_visible` INTEGER NOT NULL, `manual_position` INTEGER, `position_in_playlist` INTEGER, `max_series_last_modified_time` INTEGER, `deleted_time` INTEGER, FOREIGN KEY(`playlist_id`) REFERENCES `playlists`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
PRAGMA user_version=60;
